const s = wb.getWorksheet('Sheet1');
s.getRange('J3:L6').setComputedValues ? null : null;
const cols = ['D','E','F'], out = ['J','K','L'];
for (let r = 3; r <= 6; r++) for (let c = 0; c < 3; c++)
  s.getRange(out[c] + r).setValue(`=SUMPRODUCT(--($B$1:$B$43=$H${r}),$C$1:$C$43,${cols[c]}$1:${cols[c]}$43)/$I${r}`);
const idx = [3,9,15,21,27,33,39];
const check = async (col, off) => {
  const num = idx.map(i => `C${i+off}*${col}${i+off}`).join('+');
  const den = idx.map(i => `C${i+off}`).join('+');
  return await wb.evaluate(`=(${num})/(${den})`);
};
log('J3 check', await check('D',0), 'K4 check', await check('E',1), 'L6 check', await check('F',3), 'J6 check', await check('D',3));
